import { create } from 'zustand';
import { login as loginApi } from '../api/authService';
import { setAccessToken } from '../api/tokenService';
import { getCategoriesList } from '../api/categoriesService'; // <-- Replace with your actual API service function

// localStorage keys
const STORAGE_KEYS = {
  ACCESS_TOKEN: 'wms_access_token',
  USER_DATA: 'wms_user_data',
  IS_LOGGED_IN: 'wms_is_logged_in',
  USERNAME: 'wms_username',
};

// 1. Define the User Data shape explicitly
interface UserData {
  id: any;
  employee_id: any;
  employee_number: any;
  firstname: string;
  lastname: string;
  middlename: string;
  username: string;
  position_name: string;
  position_id: any;
  status: any;
  status_id: any;
  date_created: string;
  date_updated: string;
}

export interface MenuItem {
  key: string;
  label: string;
  title?: string;
  children?: MenuItem[];
}

export interface CategoryOption {
  value: string | number;
  label: string;    
}

// 2. Define the Complete Store State and Actions Interface
interface AppViewModelState {
  // State variables
  isLoggedIn: boolean;
  accessToken: string;
  userData: UserData | null;
  username: string;
  password?: string;
  activeMenu: string;
  activeTitle?: string;
  activeLabel?: string;
  sidebarCollapsed: boolean;
  formError: string;
  isLoading: boolean;
  isCategoriesLoading: boolean;
  menuItems: MenuItem[];
  
  categories: Array<{ id: string | number; name: string }>; 
  categoryDropdown: CategoryOption[];

  // Actions / Methods
  saveAuthState: (isLoggedIn: boolean, accessToken: string, userData: UserData | null, username: string) => void;
  setField: (name: string, value: any) => void;
  toggleSidebar: () => void;
  selectMenu: (key: string, title: string, label: string) => void;
  fetchInventoryCategories: () => Promise<void>;
  login: () => Promise<{ success: boolean; error?: string; data?: any }>;
  logout: () => void;
}

// Base menu configuration (Inventory will be populated dynamically)
const BASE_MENU_ITEMS: MenuItem[] = [
  {
    key: 'inventory',
    label: 'Inventory',
    title: 'Inventory Management',
    children: [], // Populated dynamically via fetchInventoryCategories
  },
  {
    key: 'replenishment',
    label: 'Replenishment',
    title: 'Stock Replenishment',
    children: [
      { key: 'replenishment_management', label: 'Stock Management', title: 'Stock Management' },
      { key: 'suppliers', label: 'Suppliers', title: 'Suppliers' },
    ],
  },
  { key: 'sales', label: 'Sales', title: 'Sales Management' },
  { key: 'returns', label: 'Returns', title: 'Returns Management' },
  { key: 'employees', label: 'Employees', title: 'Employees Management' },
  {
    key: 'reports',
    label: 'Reports',
    title: 'Daily Sales Reports',
    children: [
      { key: 'reports', label: 'Daily Sales - All', title: 'Daily Sales - All' },
      { key: 'reports|cements|21', label: 'Daily Sales - Cement', title: 'Daily Sales - Cement' },
      { key: 'reports|steel materials|1421', label: 'Daily Sales - RSB 10', title: 'Daily Sales - RSB 10' },
      { key: 'reports|steel materials|1422', label: 'Daily Sales - RSB 12', title: 'Daily Sales - RSB 12' },
      { key: 'reports|steel materials|1423', label: 'Daily Sales - RSB 16', title: 'Daily Sales - RSB 16' },
      { key: 'reports|steel materials|1898', label: 'Daily Sales - Gravel', title: 'Daily Sales - Gravel' },
      { key: 'reports|steel materials|309', label: 'Daily Sales - CHB #4', title: 'Daily Sales - CHB #4' },
      { key: 'reports|steel materials|310', label: 'Daily Sales - CHB #5', title: 'Daily Sales - CHB #5' },
      { key: 'reports|unmonitored', label: 'Daily Sales - Unmonitored', title: 'Daily Sales - Unmonitored' },
      { key: 'stockin', label: 'Stock-In (Purchases) Log', title: 'Stock-In (Purchases) Log' },
    ],
  },
  {
    key: 'ledgers',
    label: 'Ledgers',
    title: 'Monthly Business Ledger',
    children: [
      // { key: 'ledger', label: 'Daily Business Ledger', title: 'Daily Business Ledger' },
      { key: 'monthly_ledger', label: 'Monthly Business Ledger', title: 'Monthly Business Ledger' },
      { key: 'monitored_ledger', label: 'Monitored Ledger', title: 'Monitored Ledger' },
      { key: 'sand_ledger', label: 'Gravel and Sand Ledger', title: 'Sand Ledger' },
      // { key: 'gravel_ledger', label: 'Gravel Ledger', title: 'Gravel Ledger' },
      { key: 'chb_ledger', label: 'CHB Ledger', title: 'CHB Ledger' },
    ],
  },
  { key: 'categories', label: 'Categories', title: 'Categories' },
  { key: 'logout', label: 'Logout' },
];

const loadInitialState = (): Pick<AppViewModelState, 'isLoggedIn' | 'accessToken' | 'userData' | 'username' | 'menuItems'> => {
  try {
    const accessToken = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
    const userDataStr = localStorage.getItem(STORAGE_KEYS.USER_DATA);
    const isLoggedIn = localStorage.getItem(STORAGE_KEYS.IS_LOGGED_IN) === 'true';
    const username = localStorage.getItem(STORAGE_KEYS.USERNAME) || '';

    if (accessToken && userDataStr && isLoggedIn) {
      setAccessToken(accessToken);
      const userData: UserData = JSON.parse(userDataStr);
      console.log('loadInitialState userData', userData);
      
      // Filter menus based on the stored user's position_id right on load!
      const filteredMenus = getMenusByPosition(userData.position_id);
      console.log('loadInitialState filteredMenus', filteredMenus);

      return {
        isLoggedIn: true,
        accessToken,
        userData,
        username,
        menuItems: filteredMenus, // <-- This ensures it stays filtered on refresh
      };
    }
  } catch (error) {
    console.error('Error loading initial state:', error);
  }

  return {
    isLoggedIn: false,
    accessToken: '',
    userData: null,
    username: '',
    menuItems: BASE_MENU_ITEMS,
  };
};

const findMenuItem = (items: MenuItem[], targetKey: string): MenuItem | undefined => {
  for (const item of items) {
    if (item.key === targetKey) return item;
    if (item.children) {
      const found = findMenuItem(item.children, targetKey);
      if (found) return found;
    }
  }
  return undefined;
};

// Define menu access rules based on position_id
const getMenusByPosition = (positionId: any): MenuItem[] => {
  const posId = Number(positionId);

  // Deep clone BASE_MENU_ITEMS to prevent state sharing/mutations between users
  const clonedMenuItems: MenuItem[] = JSON.parse(JSON.stringify(BASE_MENU_ITEMS));

  switch (posId) {
    case 1:
      return clonedMenuItems;

    case 2:
      return clonedMenuItems.filter((item) => 
        ['inventory', 'sales', 'replenishment', 'reports', 'returns', 'logout'].includes(item.key)
      );

    case 3:
      return clonedMenuItems.filter((item) => 
        ['inventory', 'categories', 'logout'].includes(item.key)
      );

    default:
      return clonedMenuItems.filter((item) => item.key === 'logout');
  }
};

const getInitialActiveMenuState = (): { activeMenu: string; activeTitle: string; activeLabel: string; } => {
  const defaultMenu = BASE_MENU_ITEMS[0];
  const fallback = {
    activeMenu: defaultMenu.key,
    activeTitle: defaultMenu.title || defaultMenu.label,
    activeLabel: defaultMenu.label
  };

  if (typeof window === 'undefined') return fallback;

  const params = new URLSearchParams(window.location.search);
  const menuParam = params.get('menu');

  if (!menuParam) return fallback;

  const decodedKey = decodeURIComponent(menuParam);
  const menuParts = decodedKey.split('|'); 
  const menuParent = menuParts[0];

  if (menuParent === 'monthly_ledger_view') {
    const date_value = menuParts[2];
    return {
      activeMenu: decodedKey,
      activeTitle: `Monthly Ledger View - ${date_value}`,
      activeLabel: `Monthly Ledger View - ${date_value}`,
    };
  } else if (menuParent === 'monitored_ledger_view') {
    const date_value = menuParts[2];
    return {
      activeMenu: decodedKey,
      activeTitle: `Monitored Ledger View - ${date_value}`,
      activeLabel: `Monitored Ledger View - ${date_value}`,
    };
  } else if (menuParent === 'substrates_ledger_view') {
    const date_value = menuParts[2];
    return {
      activeMenu: decodedKey,
      activeTitle: `Substrates Ledger View - ${date_value}`,
      activeLabel: `Substrates Ledger View - ${date_value}`,
    };
  } else if (menuParent === 'gravel_ledger_view') {
    const date_value = menuParts[2];
    return {
      activeMenu: decodedKey,
      activeTitle: `Gravel Ledger View - ${date_value}`,
      activeLabel: `Gravel Ledger View - ${date_value}`,
    };
  } else if (menuParent === 'chb_ledger_view') {
    const date_value = menuParts[2];
    return {
      activeMenu: decodedKey,
      activeTitle: `CHB Ledger View - ${date_value}`,
      activeLabel: `CHB Ledger View - ${date_value}`,
    };
  } else if (menuParent === 'sand_ledger_view') {
    const date_value = menuParts[2];
    return {
      activeMenu: decodedKey,
      activeTitle: `Gravel and Sand Ledger View - ${date_value}`,
      activeLabel: `Gravel Sand Ledger View - ${date_value}`,
    };
  } else {
    const matchedItem = findMenuItem(BASE_MENU_ITEMS, decodedKey);
    return {
      activeMenu: decodedKey,
      activeTitle: matchedItem?.title || defaultMenu.label || '',
      activeLabel: matchedItem?.label || '',
    };
  }
};

const initialState = loadInitialState();
const initialMenuState = getInitialActiveMenuState();

const useAppViewModel = create<AppViewModelState>((set, get) => ({
  ...initialState,
  ...initialMenuState,
  password: '',
  sidebarCollapsed: false,
  formError: '',
  isLoading: false,
  isCategoriesLoading: false,
  // menuItems: BASE_MENU_ITEMS,
  categories: [],
  categoryDropdown: [],

  saveAuthState: (isLoggedIn, accessToken, userData, username) => {
    try {
      if (isLoggedIn && accessToken && userData) {
        localStorage.setItem(STORAGE_KEYS.IS_LOGGED_IN, 'true');
        localStorage.setItem(STORAGE_KEYS.ACCESS_TOKEN, accessToken);
        localStorage.setItem(STORAGE_KEYS.USER_DATA, JSON.stringify(userData));
        localStorage.setItem(STORAGE_KEYS.USERNAME, username);
      } else {
        localStorage.removeItem(STORAGE_KEYS.IS_LOGGED_IN);
        localStorage.removeItem(STORAGE_KEYS.ACCESS_TOKEN);
        localStorage.removeItem(STORAGE_KEYS.USER_DATA);
        localStorage.removeItem(STORAGE_KEYS.USERNAME);
      }
    } catch (error) {
      console.error('Error saving auth state:', error);
    }
  },

  setField: (name, value) => set((state) => ({ ...state, [name]: value, formError: '' })),

  toggleSidebar: () => set((state) => ({ sidebarCollapsed: !state.sidebarCollapsed })),

  selectMenu: (key: string, title: string, label: string) => {
    if (key === 'logout') {
      get().logout();
      return;
    }
    set({ activeMenu: key, activeTitle: title, activeLabel: label });
  },

  fetchInventoryCategories: async () => {
    set({ isCategoriesLoading: true });
    try {
      const response = await getCategoriesList({order:'ASC', sort:'name'});
      
      const rawCategories = response.data.data || response || [];
      
      const inventoryChildren = rawCategories.map((cat: { id?: string | number; name: string; tag: string}) => ({
        key: `inventory|${cat.name.toLowerCase().replace(/[\s&]+/g, '_')}`,
        label: cat.name,
        tag: cat.tag,
        title: `Inventory Management - ${cat.name}`,
      }));
      
      const dropdownOptions: CategoryOption[] = rawCategories.map((cat: { id: string | number; name: string;  tag: string}) => ({
        value: cat.id, 
        label: cat.name,
        tag: cat.tag,
      }));

      set((state) => ({
        isCategoriesLoading: false,
        categories: rawCategories,
        categoryDropdown: dropdownOptions, // Saved in store!
        menuItems: state.menuItems.map((item) =>
          item.key === 'inventory' ? { ...item, children: inventoryChildren } : item
        ),
      }));
    } catch (error) {
      console.error('Failed to fetch inventory categories:', error);
      set({ isCategoriesLoading: false });
    }
  },

  login: async () => {
    const { username, password } = get();

    if (!username && !password) {
      set({ formError: 'Please enter both username and password' });
      return { success: false, error: 'Please enter both username and password' };
    }

    if (!username) {
      set({ formError: 'Username is required' });
      return { success: false, error: 'Username is required' };
    }

    if (!password) {
      set({ formError: 'Password is required' });
      return { success: false, error: 'Password is required' };
    }

    set({ isLoading: true, formError: '' });

    try {
      const result = await loginApi(username, password);

      if (result.success) {
        const { data } = result;

        setAccessToken(data.access_token || '');

        const userData: UserData = {
          id: data.id,
          employee_id: data.employee_id,
          employee_number: data.employee_number,
          firstname: data.firstname,
          lastname: data.lastname,
          middlename: data.middlename,
          username: data.username,
          position_name: data.position_name,
          position_id: data.position_id,
          status: data.status,
          status_id: data.status_id,
          date_created: data.date_created,
          date_updated: data.date_updated,
        };

        get().saveAuthState(true, data.access_token || '', userData, username);

        const allowedMenus = getMenusByPosition(userData.position_id);

        set({
          isLoggedIn: true,
          activeTitle: '',
          activeLabel: '',
          formError: '',
          isLoading: false,
          accessToken: data.access_token || '',
          userData,
          menuItems: allowedMenus,
        });
        
        if (userData.position_id == 1 || userData.position_id == 2 || userData.position_id == 3) {
          get().fetchInventoryCategories();
        }
      } else {
        set({ formError: result.error || 'Login failed', isLoading: false });
      }

      return result;
    } catch (error) {
      set({ formError: 'An unexpected error occurred', isLoading: false });
      return { success: false, error: 'An unexpected error occurred' };
    }
  },

  logout: () => {
    const isConfirmed = window.confirm('Are you sure you want to logout?');

    if (isConfirmed) {
      setAccessToken('');
      get().saveAuthState(false, '', null, '');

      set({
        isLoggedIn: false,
        username: '',
        password: '',
        activeMenu: 'inventory',
        activeTitle: '',
        activeLabel: '',
        sidebarCollapsed: false,
        formError: '',
        accessToken: '',
        userData: null,
        isLoading: false,
        menuItems: JSON.parse(JSON.stringify(BASE_MENU_ITEMS)),
        categories: [],
        categoryDropdown: [],
      });
    }
  },
}));

export default useAppViewModel;